<script setup lang="ts">import{onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const values=ref<components['schemas']['QARecord'][]>([]);const error=ref('');onMounted(async()=>{try{values.value=requireData(await client.GET('/api/admin/qa/records'))}catch(cause){error.value=errorMessage(cause)}});async function feature(value:components['schemas']['QARecord']){const title=prompt('精选回答标题',value.question);if(!title)return;try{requireData(await client.PUT('/api/admin/qa/records/{id}/featured',{params:{path:{id:value.id}},body:{title,sortKey:new Date(value.createdAt).toISOString()}}))}catch(cause){error.value=errorMessage(cause)}}</script>
<template><PageHeader title="问答记录"/><p v-if="error" class="text-danger">{{ error }}</p><article v-for="value in values" :key="value.id" class="mb-4 rounded-card border border-border p-4"><strong>{{ value.question }}</strong><p class="mt-2 whitespace-pre-wrap">{{ value.answer }}</p><small class="text-muted">{{ value.language }} · {{ value.cost }}</small><button class="ms-4 text-primary" @click="feature(value)">设为精选</button></article></template>
